exercise.solution:
def compare(base,candidate):
    if len(base)!=len(candidate): raise ValueError('paired lengths')
    return {'wins':sum(c and not b for b,c in zip(base,candidate)), 'losses':sum(b and not c for b,c in zip(base,candidate)), 'ties':sum(b==c for b,c in zip(base,candidate))}

exercise.tests:
assert compare([True,False,True],[True,True,False])=={'wins':1,'losses':1,'ties':1}
try: compare([], [True]); assert False
except ValueError: pass

